import { Marquee } from "@nativecn/ui/premium/motion/marquee";

export default function App() {
  const items = ["React Native", "Expo", "Reanimated", "NativeCN", "TypeScript"];
  return (
    <Marquee speed={50}>
      {items.map((item, i) => (
        <Text key={i} style={{ marginRight: 32, color: "#a855f7" }}>{item}</Text>
      ))}
    </Marquee>
  );
}
